<?php
$site=getenv('GE_QA_WP_ROOT'); if (!$site) { throw new Exception('Set GE_QA_WP_ROOT to an isolated restore'); } require $site.'/wp-load.php';
if(DB_NAME!=='graph_restore_v2')throw new Exception('isolation');
$c=json_decode(file_get_contents(__DIR__.'/qa-context.json'),true);wp_set_current_user($c['staff']);$o=wc_get_order($c['order_id']);$o->update_meta_data(GE_WTP_Workflow::VERSION_META,'1');$docs=(array)$o->get_meta(GE_WTP_Documents::META_KEY,true);foreach($docs as &$d){if($d['id']===$c['candidate_version_id'])$d['status']='candidate';}unset($d);$o->update_meta_data(GE_WTP_Documents::META_KEY,$docs);$o->save();$item=$o->get_item($c['item_id']);$item->update_meta_data('_ge_item_status','received');$item->save();
$input=array('order_id'=>$c['order_id'],'version_id'=>$c['candidate_version_id'],'decision'=>'select');$r=GE_WTP_AI_Artwork::execute_action('graph.artwork.select_version',$input);if(is_wp_error($r))throw new Exception($r->get_error_message());$i=wc_get_order($c['order_id'])->get_item($c['item_id']);if($i->get_meta(GE_WTP_Workflow::ITEM_STATE_META,true)!=='received')throw new Exception('Invalid workflow state');echo "PASS selection uses canonical received state\n";
$o=wc_get_order($c['order_id']);$docs=(array)$o->get_meta(GE_WTP_Documents::META_KEY,true);foreach($docs as &$d){if($d['id']===$c['candidate_version_id'])$d['status']='candidate';}unset($d);$o->update_meta_data(GE_WTP_Documents::META_KEY,$docs);$o->save();$i->update_meta_data('_ge_item_status','production');$i->save();$r=GE_WTP_AI_Artwork::execute_action('graph.artwork.select_version',$input);if(!is_wp_error($r)||$r->get_error_code()!=='released')throw new Exception('Released guard failed');echo "PASS released product cannot swap candidate\n";
$o=wc_get_order($c['order_id']);$o->delete_meta_data(GE_WTP_Workflow::VERSION_META);$o->save();$r=GE_WTP_AI_Artwork::execute_action('graph.artwork.select_version',$input);if(!is_wp_error($r)||$r->get_error_code()!=='released')throw new Exception('Legacy released guard failed');echo "PASS legacy production guarded\n";
